   350|                            <td>Cardiac Stent/Angioplasty</td>
   351|                            <td>$8,000</td>
   352|                            <td>$18,000</td>
   353|                            <td>Cardiac specialty hospital</td>
   354|                        </tr>
   355|                        <tr>
   356|                            <td>Total Knee Replacement</td>
   357|                            <td>$6,000</td>
   358|                            <td>$12,000</td>
   359|                            <td>Orthopedic specialty</td>
   360|                        </tr>
   361|                        <tr>
