   364|                            <td>$15,000</td>
   365|                            <td>Orthopedic specialty</td>
   366|                        </tr>
   367|                        <tr>
   368|                            <td>Spinal Fusion (1-2 levels)</td>
   369|                            <td>$10,000</td>
   370|                            <td>$22,000</td>
   371|                            <td>Spine center</td>
   372|                        </tr>
   373|                        <tr>
   374|                            <td>Cancer Surgery (major)</td>
   375|                            <td>$8,000</td>
   376|                            <td>$20,000</td>
   377|                            <td>Oncology center</td>
   378|                        </tr>
   379|                        <tr>
